  'about.quote.text' : { en: '“The numbers do not tell you what will happen. They tell you what you are here to learn — and what you are here to express. You still have to walk the path.”', es: '“Los números no te dicen qué va a pasar. Te dicen qué estás aquí para aprender — y qué estás aquí para expresar. Aún tienes que caminar el camino.”' },
